    private class P(val d: String, val alpha: Float, val evenOdd: Boolean, val fill: Boolean, val stroke: Float, val cap: StrokeCap, val join: StrokeJoin)

    private fun build(name: String, vararg paths: P): ImageVector =
        ImageVector.Builder("Solar.$name", 24.dp, 24.dp, 24f, 24f).apply {
            paths.forEach { p ->
                addPath(
                    addPathNodes(p.d),
                    pathFillType = if (p.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                    fill = if (p.fill) SolidColor(Color.Black) else null, fillAlpha = p.alpha,
                    stroke = if (p.stroke > 0f) SolidColor(Color.Black) else null, strokeAlpha = p.alpha,
                    strokeLineWidth = p.stroke, strokeLineCap = p.cap, strokeLineJoin = p.join,
                )
            }
        }.build()
}
